	(231, 's47wru5a6djsesouezoo6dx5', 'Equipo de Investigación en Gestión Estratégica y Políticas Públicas (EIGEPP)', '2026', 'CIENCIAS ADMINISTRATIVAS Y HUMANAS', 'ADMINISTRACIÓN', 'Dr. Alejandro Ticona Machaca', 'Administración General.\nGestión estratégica.\nGestión pública', 'Félix Henry Gutierrez Castillo.\n- John Davy Tapia Sanizo.\n- Roger Freddy Fernandez Burgos.\n- Delia Concepción Cahuana Pacco.\n- Grisell Aliaga Melo.\n- Miguel Martin Arroyo Beltran.\n- Litzbel Charaja Fernandez\n- Bertelly Turpo Aliaga.\n- Yeny Roxana Estrada Cahuapaza, (Doc. FICA).\n- Saby Yazmina Cairo Méndez. (Doc. Contratado).\n- Rómulo Huacasi Gonzales.', '2026-08-18 22:26:21.331000', '2026-08-19 15:33:52.377000', NULL, NULL, 1, NULL, 'Generar conocimientos científicos, tecnológicos e innovaciones que impacten positivamente en la sociedad.\nPromover una cultura investigadora en la UNA Puno en la línea de investigación de administración general.', NULL, NULL, NULL, NULL),
	(233, 'vjxm4r7657c8nyxyvo6pxk9d', 'ILLAPA', '2026', 'INGENIERÍA ECONÓMICA', 'Ingeniería Económica', 'Dr. Polan Franbalt Ferro Gonzales', 'Economía y Desarrollo", entendida como el estudio de las interrelaciones entre crecimiento económico, estructuras productivas, instituciones, políticas públicas y bienestar humano.', 'Dr. Edwin Joel Garabito Monteagudo.\n- Dr. Vladimir Ylich Felipe Mamani Sonco.\nColadorador:\n- Dennys Rosmil Ochochoque Muchica.', '2026-08-18 22:26:22.103000', '2026-08-19 15:14:32.281000', NULL, NULL, 1, NULL, 'Consolidar un grupo de investigación Emergente en "Economía y desarrollo" que genera evidencias científica pertinente para la región altiplánica y el país, contribuyendo al diseño de políticas públicas, la mejora de la competitividad territorial y el desarrollo humano sostenible, en coherencia con las líneas de investigación y planes estratégicos de la UNA Puno y el Plan Nacional de Ciencia, Tecnología e Investigación.', NULL, NULL, NULL, NULL),
